style.css:
@-moz-document domain("sweezy.community") {
/* Sanrio Background */
  body {
    background-color: #f8e1f4; /* Soft pastel pink background */
    background-image: url('https://your-link-to-sanrio-image.jpg'); /* Sanrio-themed image */
    background-repeat: no-repeat;
    background-size: cover; /* Ensure the image covers the full background */
    background-position: center;
    color: #333; /* Dark text color to contrast the pastel background */
    font-family: 'Arial', sans-serif;
  }

  /* Sanrio-themed header */
  header {
    background-color: #ffb6c1; /* Light pink background for header */
    text-align: center;
    padding: 20px;
  }

  header h1 {
    font-family: 'Comic Sans MS', cursive, sans-serif;
    color: #ff69b4; /* Sanrio-like pink color for header text */
    font-size: 3em;
  }

  /* Sanrio buttons */
  button {
    background-color: #ffccff; /* Light pink button */
    color: #ff69b4; /* Pink text */
    border: none;
    padding: 10px 20px;
    border-radius: 12px; /* Rounded button corners */
    font-size: 1.2em;
    cursor: pointer;
  }

  button:hover {
    background-color: #ff99cc; /* Slightly darker pink on hover */
  }

  /* Sanrio footer */
  footer {
    background-color: #ffe4e1; /* Very light pink footer */
    text-align: center;
    padding: 10px;
  }

  footer p {
    font-size: 1em;
    color: #ff69b4;
  }
}
